const j = $input.first().json;
const body = j.body && typeof j.body === 'object' ? j.body : j;
const secret = String($env.CASTUO_WEBHOOK_IOT_SECRET || '').trim();
if (secret) {
  const h = j.headers || {};
  const auth = String(h.authorization || h.Authorization || '');
  if (auth !== 'Bearer ' + secret && h['x-castuo-token'] !== secret) {
    throw new Error('Webhook IoT: token inválido');
  }
}
return [
  {
    json: {
      payload: {
        kind: 'iot_sensor',
        sensor_id: body.sensor_id,
        value: body.value,
        type: body.type,
        location: body.location,
        battery: body.battery,
        signal: body.signal,
        timestamp: body.timestamp || new Date().toISOString(),
      },
      _raw: body,
    },
  },
];

const r = $input.first().json;
const p = $('Build_IoT_Payload').first().json.payload;
if (r.errors && r.errors.length) {
  throw new Error('LangGraph: ' + r.errors.join('; '));
}
let summary = '';
let alerts = [];
let actions = [];
try {
  const o = JSON.parse(r.analysis);
  if (o.summary != null) summary = String(o.summary);
  if (Array.isArray(o.alerts)) alerts = o.alerts.map(String);
  if (Array.isArray(o.recommended_actions)) actions = o.recommended_actions.map(String);
} catch (e) {
  summary = String(r.analysis || '').slice(0, 500);
}
return [
  {
    json: {
      sensor_id: p.sensor_id,
      value: p.value,
      type: p.type,
      location: p.location,
      trace_hash: r.trace_hash || '',
      summary,
      alerts,
      recommended_actions: actions,
      gaia_http_status: r.gaia_http_status,
      analysis_raw: r.analysis || '',
    },
  },
];
